class Solution:
    def addMinimum(self, word: str) -> int:
        exp = 0
        res = 0
        for c in word:
            cur = ord(c) - 97
            res += (cur - exp) % 3
            exp = (cur + 1) % 3
        res += (2 - exp) % 3
        return res

