class Solution {
public:
    int addMinimum(string word) {
        int res = 0;
        char exp = 'a';
        auto nxt = [](char c) { return c == 'a' ? 'b' : (c == 'b' ? 'c' : 'a'); };
        for (char c : word) {
            while (exp != c) { res++; exp = nxt(exp); }
            exp = nxt(exp);
        }
        while (exp != 'a') { res++; exp = nxt(exp); }
        return res;
    }
};

