class Solution {
    public int addMinimum(String word) {
        int res = 0;
        char exp = 'a';
        java.util.function.UnaryOperator<Character> nxt = c -> c == 'a' ? 'b' : (c == 'b' ? 'c' : 'a');
        for (char c : word.toCharArray()) {
            while (exp != c) { res++; exp = nxt.apply(exp); }
            exp = nxt.apply(exp);
        }
        while (exp != 'a') { res++; exp = nxt.apply(exp); }
        return res;
    }
}

